# CAL loop, stripped to its logic
while True:
    batch = top_k(model.score(unreviewed), k=200)   # most likely relevant first
    labels = reviewers.code(batch)                    # humans train by reviewing
    training += zip(batch, labels)
    model.fit(training)                               # retrain every batch
    hit_rate = sum(labels) / len(labels)
    if hit_rate < 0.02 for several consecutive batches:
        if elusion_sample(unreviewed, n=2400).responsive_rate() is acceptable:
            break                                     # stop; estimate recall
